const defaults={theme:'custom',accent:'#8d9cff',bg1:'#10182f',bg2:'#263b68',surface:'#192037',text:'#f6f7ff',blur:24,transparency:78,radius:22,dockSize:44,dockPosition:'bottom',dockVisible:true,animations:'full',animationSpeed:100};settings={...defaults,...settings};
function apply(){document.documentElement.style.setProperty('--accent',settings.accent);document.documentElement.style.setProperty('--blur',settings.blur+'px');document.documentElement.style.setProperty('--trans',settings.transparency/100);document.documentElement.style.setProperty('--radius',settings.radius+'px');document.documentElement.style.setProperty('--bg1',settings.bg1||'#10182f');document.documentElement.style.setProperty('--bg2',settings.bg2||'#263b68');document.documentElement.style.setProperty('--surface',settings.surface||'#192037');document.documentElement.style.setProperty('--text',settings.text||'#f6f7ff');document.documentElement.style.setProperty('--glass','color-mix(in srgb, '+(settings.surface||'#192037')+' '+(settings.transparency||78)+'%, transparent)');document.documentElement.style.setProperty('--motion-scale',String((settings.animationSpeed??100)/100));document.body.classList.toggle('animations-off',settings.animations==='none');document.body.classList.toggle('animations-subtle',settings.animations==='subtle');document.body.classList.toggle('light-theme',settings.theme==='light');document.body.classList.toggle('custom-theme',settings.theme==='custom');$('#dock').style.display=settings.dockVisible?'flex':'none';$('#dock').style.left=settings.dockPosition==='left'?'12px':settings.dockPosition==='right'?'auto':'50%';$('#dock').style.right=settings.dockPosition==='right'?'12px':'auto';$('#dock').style.transform=settings.dockPosition==='left'||settings.dockPosition==='right'?'translateY(50%)':'translateX(-50%)';$('#dock').style.top=settings.dockPosition==='top'?'12px':'auto';$('#dock').style.bottom=settings.dockPosition==='top'?'auto':'12px';}
