 function language(n){let ext=(n.split('.').pop()||'').toLowerCase();return ({js:'JavaScript',mjs:'JavaScript',ts:'TypeScript',html:'HTML',css:'CSS',json:'JSON',py:'Python',md:'Markdown',txt:'Plain Text',xml:'XML',svg:'SVG',sh:'Shell'})[ext]||'Plain Text'}
