if(id==='settings'){const page=root.querySelector('#settings-page');const show=tab=>{page.innerHTML=tab==='appearance'?'<h3>Appearance</h3><label>Theme style <select id="theme"><option value="dark">Dark</option><option value="light">Light</option><option value="custom">Custom</option></select></label><label>Accent color <input type="color" id="accent"></label><label>Wallpaper tone 1 <input type="color" id="bg1"></label><label>Wallpaper tone 2 <input type="color" id="bg2"></label><label>Glass color <input type="color" id="surface"></label><label>Text color <input type="color" id="text"></label><label>Glass blur <input type="range" id="blur" min="0" max="40"></label><label>Transparency <input type="range" id="transparency" min="35" max="95"></label><label>Corner roundness <input type="range" id="radius" min="4" max="32"></label>':tab==='animations'?'<h3>Animations</h3><label>Motion style <select id="animations"><option value="full">Full</option><option value="subtle">Subtle</option><option value="none">Off</option></select></label><label>Animation speed <input type="range" id="animationSpeed" min="25" max="175" step="5"></label><p class="settings-hint">Choose how lively window, menu and button transitions feel.</p>':tab==='dock'?'<h3>Dock</h3><label>Position <select id="dockPosition"><option>bottom</option><option>top</option><option>left</option><option>right</option></select></label><label>Dock visible <input type="checkbox" id="dockVisible"></label>':'<h3>'+tab+'</h3><p>My OS browser settings are stored on this device.</p>';page.querySelectorAll('input,select').forEach(el=>{let k=el.id;el.type==='checkbox'?el.checked=!!settings[k]:el.value=settings[k]??'';el.oninput=()=>{settings[k]=el.type==='checkbox'?el.checked:el.type==='range'?+el.value:el.value;saveSettings()}})};root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>show(b.dataset.tab));show('appearance')}
