function openApp(id){if(open.has(id)){let old=open.get(id);old.classList.remove('minimized');focus(old);dockState();return}let app=APPS.find(x=>x[0]===id);if(!app)return;let w=document.createElement('section');w.className='window';w.dataset.app=id;w.style.left=Math.max(12,90+open.size*24)+'px';w.style.top=Math.max(12,65+open.size*20)+'px';w.style.zIndex=++z;w.innerHTML='<header class="window-header"><div class="traffic"><button class="close" title="Close">×</button><button class="min" title="Minimize">−</button><button class="max" title="Maximize">□</button></div><b>'+app[2]+'</b><button class="x">✕</button></header><div class="window-content"></div><div class="resize-handle"></div>';$('#windows').append(w);open.set(id,w);let content=w.querySelector('.window-content');legacy(id,content);w.querySelectorAll('.close,.x').forEach(b=>b.onclick=()=>{w.classList.add('closing');setTimeout(()=>{w.remove();open.delete(id);dockState()},180)});w.querySelector('.min').onclick=()=>{w.classList.add('minimized');w.classList.remove('active');dockState()};w.querySelector('.max').onclick=()=>toggleMax(w);w.querySelector('.window-header').ondblclick=e=>{if(!e.target.closest('button'))toggleMax(w)};w.onpointerdown=()=>focus(w);let start;const header=w.querySelector('.window-header');let drag=null;header.addEventListener('pointerdown',e=>{if((e.pointerType==='mouse'&&e.button!==0)||e.target.closest('button')||w.classList.contains('maximized'))return;e.preventDefault();focus(w);const rect=w.getBoundingClientRect();drag={x:e.clientX-rect.left,y:e.clientY-rect.top,id:e.pointerId};try{header.setPointerCapture(e.pointerId)}catch{};});const moveWindow=e=>{if(!drag||e.pointerId!==drag.id)return;const maxX=Math.max(0,innerWidth-w.offsetWidth),maxY=Math.max(0,innerHeight-w.offsetHeight);w.style.left=Math.min(maxX,Math.max(0,e.clientX-drag.x))+'px';w.style.top=Math.min(maxY,Math.max(0,e.clientY-drag.y))+'px'};const stopDrag=e=>{if(drag&&e.pointerId===drag.id){drag=null;try{if(header.hasPointerCapture(e.pointerId))header.releasePointerCapture(e.pointerId)}catch{}}};document.addEventListener('pointermove',moveWindow,true);document.addEventListener('pointerup',stopDrag,true);document.addEventListener('pointercancel',stopDrag,true);const handle=w.querySelector('.resize-handle');let resize=null;handle.addEventListener('pointerdown',e=>{if((e.pointerType==='mouse'&&e.button!==0)||w.classList.contains('maximized'))return;e.preventDefault();e.stopPropagation();focus(w);const rect=w.getBoundingClientRect();resize={id:e.pointerId,x:e.clientX,y:e.clientY,width:rect.width,height:rect.height,left:rect.left,top:rect.top};try{handle.setPointerCapture(e.pointerId)}catch{}});const resizeWindow=e=>{if(!resize||e.pointerId!==resize.id)return;const maxW=Math.max(260,innerWidth-resize.left-4),maxH=Math.max(200,innerHeight-resize.top-4);const width=Math.min(maxW,Math.max(260,resize.width+e.clientX-resize.x)),height=Math.min(maxH,Math.max(200,resize.height+e.clientY-resize.y));w.style.width=width+'px';w.style.height=height+'px'};document.addEventListener('pointermove',resizeWindow,true);const stopResize=e=>{if(!resize||e.pointerId!==resize.id)return;resize=null;try{if(handle.hasPointerCapture(e.pointerId))handle.releasePointerCapture(e.pointerId)}catch{}};document.addEventListener('pointerup',stopResize,true);document.addEventListener('pointercancel',stopResize,true);focus(w);dockState();$('#launcher').classList.add('hidden')}
