function dockState(){const bar=$('#dock-apps');bar.innerHTML=[...open.keys()].map(id=>{let a=APPS.find(x=>x[0]===id),w=open.get(id);return a&&w?'<button data-app="'+id+'" class="running '+(w.classList.contains('active')?'focused':'unfocused')+'" title="'+a[2]+'">'+a[1]+'</button>':''}).join('')}
function toggle(id){['launcher','control-center','notifications'].forEach(x=>{if(x!==id)$('#'+x).classList.add('hidden')});$('#'+id).classList.toggle('hidden')}
document.addEventListener('click',e=>{let pin=e.target.closest('[data-pin]');if(pin){let id=pin.dataset.pin,p=pinned();p=p.includes(id)?p.filter(x=>x!==id):[...p,id];localStorage.setItem('myos-pinned',JSON.stringify(p));renderApps();return}let shortcut=e.target.closest('[data-shortcut]');if(shortcut){let id=shortcut.dataset.shortcut,s=shortcuts();if(!s.includes(id))s.push(id);localStorage.setItem('myos-shortcuts',JSON.stringify(s));renderApps();toast('Desktop shortcut added');return}let a=e.target.closest('button[data-app]');if(a){openApp(a.dataset.app);return}let act=e.target.closest('[data-action]')?.dataset.action;if(act==='launcher')toggle('launcher');if(act==='close-launcher')$('#launcher').classList.add('hidden');if(act==='control')toggle('control-center');if(act==='notifications')toggle('notifications');if(act==='clear-notifications')$('#notification-list').innerHTML='<p class="muted">You’re all caught up.</p>'});
$('#app-search').oninput=e=>{const q=e.target.value.trim().toLowerCase();Array.from(document.querySelectorAll('#launcher-apps .launcher-app-wrap')).forEach(b=>{const tile=b.querySelector('.app-tile');b.hidden=!!q&&!(tile?.textContent||'').toLowerCase().includes(q)});};$('#brightness').oninput=e=>$('#desktop').style.filter='brightness('+e.target.value/100+')';$('#volume').oninput=e=>{};
$('#clock').onclick=()=>openApp('calendar');document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key===' ')toggle('launcher');if(e.key==='Escape')['launcher','control-center','notifications'].forEach(x=>$('#'+x).classList.add('hidden'))});
renderApps();apply();setInterval(()=>$('#clock').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),1000);
